import{_ as i,o as a,c as n,ae as t}from"./chunks/framework.Bwt6MOeu.js";const c=JSON.parse('{"title":"Operating Modes: Learning and Defense","description":"","frontmatter":{},"headers":[],"relativePath":"guide/operating-modes-learning-and-defense.md","filePath":"guide/operating-modes-learning-and-defense.md"}'),l={name:"guide/operating-modes-learning-and-defense.md"};function o(r,e,s,d,h,p){return a(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="operating-modes-learning-and-defense" tabindex="-1">Operating Modes: Learning and Defense <a class="header-anchor" href="#operating-modes-learning-and-defense" aria-label="Permalink to &quot;Operating Modes: Learning and Defense&quot;">​</a></h1><p>SocioProphet uses one architecture with two major operating modes:</p><ul><li><strong>Learning</strong></li><li><strong>Defense</strong></li></ul><p>This is not a contradiction. It is a controlled split.</p><h2 id="_1-why-two-modes-exist" tabindex="-1">1. Why two modes exist <a class="header-anchor" href="#_1-why-two-modes-exist" aria-label="Permalink to &quot;1. Why two modes exist&quot;">​</a></h2><p>The same system can be used to:</p><ul><li>teach structured understanding</li><li>validate defensive posture</li><li>improve policy</li><li>refine explainability</li><li>generate evidence for review and governance</li></ul><p>What changes is not the whole architecture. What changes is:</p><ul><li>the objective</li><li>the KPI set</li><li>the workflow emphasis</li><li>the acceptable output class</li><li>the review path</li></ul><h2 id="_2-learning-mode" tabindex="-1">2. Learning mode <a class="header-anchor" href="#_2-learning-mode" aria-label="Permalink to &quot;2. Learning mode&quot;">​</a></h2><p>Learning mode is the research, pedagogy, and knowledge-building lane.</p><p>It emphasizes:</p><ul><li>semantic structure</li><li>controlled topic expansion</li><li>curriculum and explanation</li><li>grammar and ontology discipline</li><li>reproducibility of understanding</li><li>annotated evidence and public-safe examples</li></ul><p>Typical outcomes include:</p><ul><li>topic maps</li><li>educational notes</li><li>structured corpora</li><li>ontology evolution</li><li>safe exemplars</li><li>reproducible demonstrations</li></ul><h2 id="_3-defense-mode" tabindex="-1">3. Defense mode <a class="header-anchor" href="#_3-defense-mode" aria-label="Permalink to &quot;3. Defense mode&quot;">​</a></h2><p>Defense mode is the validation, resilience, and hardening lane.</p><p>It emphasizes:</p><ul><li>defensive readiness</li><li>policy testing</li><li>anomaly explanation</li><li>simulation under authorization</li><li>proof of what was tested or blocked</li><li>measurable response and remediation quality</li></ul><p>Typical outcomes include:</p><ul><li>assurance reports</li><li>validation artifacts</li><li>policy findings</li><li>hardening recommendations</li><li>simulation results</li><li>remediation evidence</li></ul><h2 id="_4-shared-spine" tabindex="-1">4. Shared spine <a class="header-anchor" href="#_4-shared-spine" aria-label="Permalink to &quot;4. Shared spine&quot;">​</a></h2><p>Both modes share the same spine:</p><ul><li>governed execution</li><li>bounded capabilities</li><li>proof artifacts</li><li>provenance</li><li>human oversight</li><li>safety and authorization boundaries</li><li>reversibility</li></ul><h2 id="_5-why-the-split-matters" tabindex="-1">5. Why the split matters <a class="header-anchor" href="#_5-why-the-split-matters" aria-label="Permalink to &quot;5. Why the split matters&quot;">​</a></h2><p>The market often mixes “learning” and “automation” into one vague promise. We do not.</p><p>We keep the mode explicit so that:</p><ul><li>pedagogy does not masquerade as authority</li><li>simulation does not masquerade as permission</li><li>exploration does not outrun governance</li><li>institutions know what they are adopting</li></ul><h2 id="_6-public-safe-boundary" tabindex="-1">6. Public-safe boundary <a class="header-anchor" href="#_6-public-safe-boundary" aria-label="Permalink to &quot;6. Public-safe boundary&quot;">​</a></h2><p>Both modes are described publicly at the architectural and governance level.</p><p>Sensitive details remain restricted where publication would materially increase misuse value.</p><h2 id="_7-related-references" tabindex="-1">7. Related references <a class="header-anchor" href="#_7-related-references" aria-label="Permalink to &quot;7. Related references&quot;">​</a></h2><ul><li><a href="./deterministic-ai-and-mathematical-safety">Deterministic AI and Mathematical Safety</a></li><li><a href="./authorized-cyberdefense-and-simulation">Authorized Cyberdefense and Simulation</a></li><li><a href="./agent-plane-and-operator-workflows">Agent Plane and Operator Workflows</a></li><li><a href="./twenty-three-topic-canon">23-Topic Canon</a></li></ul>',33)])])}const m=i(l,[["render",o]]);export{c as __pageData,m as default};
